import{c as d,Q as e,j as a,m as c}from"./chunks/framework.CWBTDBPu.js";const p=JSON.parse('{"title":"YuChat 命令手册","description":"","frontmatter":{"title":"YuChat 命令手册"},"headers":[],"relativePath":"plugins/items/yu-chat/commands.md","filePath":"plugins/items/yu-chat/commands.md"}'),o={name:"plugins/items/yu-chat/commands.md"};function s(r,t,n,h,i,l){return e(),a("div",null,[...t[0]||(t[0]=[c(`<h1 id="yuchat-命令手册" tabindex="-1">YuChat 命令手册 <a class="header-anchor" href="#yuchat-命令手册" aria-label="Permalink to &quot;YuChat 命令手册&quot;">​</a></h1><p>YuChat 的主命令是 <code>/yuchat</code>，默认别名为 <code>/yc</code>、<code>/chat</code>。别名可在 <code>config.yml</code> 的 <code>commands.aliases</code> 中查看。</p><h2 id="玩家命令" tabindex="-1">玩家命令 <a class="header-anchor" href="#玩家命令" aria-label="Permalink to &quot;玩家命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/yc</code></td><td><code>yuchat.use</code>、<code>yuchat.gui</code></td><td>打开 YuChat 主 GUI。</td></tr><tr><td><code>/yc open</code></td><td><code>yuchat.use</code>、<code>yuchat.gui</code></td><td>与 <code>/yc</code> 相同，打开主 GUI。</td></tr><tr><td><code>/yc help</code></td><td>无固定权限</td><td>根据玩家已有权限显示可用命令。</td></tr><tr><td><code>/yc nick [昵称]</code></td><td><code>yuchat.nickname.use</code></td><td>修改昵称；不填昵称时进入聊天栏输入模式。</td></tr><tr><td><code>/yc signature [内容]</code></td><td><code>yuchat.signature.use</code></td><td>设置个性签名；不填内容时进入输入模式，支持 <code>\\n</code> 表示悬浮换行。</td></tr><tr><td><code>/yc sign [内容]</code></td><td><code>yuchat.signature.use</code></td><td><code>/yc signature</code> 的别名。</td></tr><tr><td><code>/yc death [内容]</code></td><td><code>yuchat.deathmessage.use</code></td><td>设置自定义死亡消息，可使用 <code>{player_display}</code>、<code>{death_cause}</code>、<code>{killer}</code>、<code>{signature}</code> 等变量。</td></tr><tr><td><code>/yc death reset</code></td><td><code>yuchat.deathmessage.use</code></td><td>重置为默认死亡消息。</td></tr><tr><td><code>/yc deathmessage [内容]</code></td><td><code>yuchat.deathmessage.use</code></td><td><code>/yc death</code> 的别名。</td></tr><tr><td><code>/yc reset</code></td><td><code>yuchat.use</code></td><td>重置玩家显示设置和已保存的聊天展示数据。</td></tr></tbody></table><h2 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to &quot;管理命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/yc admin</code></td><td><code>yuchat.admin</code></td><td>打开管理员 GUI，可创建称呼、调整经济、编辑 LuckPerms 显示组合等。</td></tr><tr><td><code>/yc reload</code></td><td><code>yuchat.reload</code></td><td>重载配置、消息、GUI、称呼和效果文件。</td></tr></tbody></table><h2 id="gui-入口" tabindex="-1">GUI 入口 <a class="header-anchor" href="#gui-入口" aria-label="Permalink to &quot;GUI 入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>说明</th></tr></thead><tbody><tr><td>主菜单</td><td>玩家配置称呼、昵称、聊天颜色、显示开关和个人设置。</td></tr><tr><td>称呼列表</td><td>左键选择并激活称呼，右键激活或取消激活。</td></tr><tr><td>称呼颜色</td><td>先选择目标称呼，再为该称呼设置独立颜色效果。</td></tr><tr><td>昵称设置</td><td>设置昵称、昵称颜色和昵称格式。</td></tr><tr><td>显示设置</td><td>切换称呼、昵称、前缀、后缀是否展示。</td></tr><tr><td>管理员 GUI</td><td>创建自定义称呼，编辑通用经济、称呼经济和 LuckPerms prefix/suffix/meta 组合。</td></tr></tbody></table><h2 id="输入模式" tabindex="-1">输入模式 <a class="header-anchor" href="#输入模式" aria-label="Permalink to &quot;输入模式&quot;">​</a></h2><p>这些命令在参数不足时会进入聊天栏输入模式：</p><table tabindex="0"><thead><tr><th>命令</th><th>输入内容</th><th>取消方式</th></tr></thead><tbody><tr><td><code>/yc nick</code></td><td>新昵称</td><td>输入 <code>cancel</code>。</td></tr><tr><td><code>/yc signature</code></td><td>个性签名</td><td>输入 <code>cancel</code>。</td></tr><tr><td><code>/yc death</code></td><td>自定义死亡消息</td><td>输入 <code>cancel</code>。</td></tr><tr><td>管理员 GUI 编辑项</td><td>配置字段、数字、颜色 ID 或多行悬浮内容</td><td>输入 <code>cancel</code>。</td></tr></tbody></table><h2 id="tab-补全" tabindex="-1">Tab 补全 <a class="header-anchor" href="#tab-补全" aria-label="Permalink to &quot;Tab 补全&quot;">​</a></h2><p>YuChat 会按发送者权限动态显示补全项。普通玩家通常能看到 <code>open</code>、<code>nick</code>、<code>signature</code>、<code>death</code>、<code>reset</code>、<code>help</code>；管理员会额外看到 <code>admin</code> 与 <code>reload</code>。</p><h2 id="常用组合" tabindex="-1">常用组合 <a class="header-anchor" href="#常用组合" aria-label="Permalink to &quot;常用组合&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yc</span></span>
<span class="line"><span>/yc nick 星河旅人</span></span>
<span class="line"><span>/yc signature 今天也在路上</span></span>
<span class="line"><span>/yc death {player_display} 被 {killer} 击败了</span></span>
<span class="line"><span>/yc death reset</span></span>
<span class="line"><span>/yc admin</span></span>
<span class="line"><span>/yc reload</span></span></code></pre></div>`,15)])])}const y=d(o,[["render",s]]);export{p as __pageData,y as default};
